"""PDF management.

* Official PDFs (weekly cause list, court-wise cause lists) are proxied from
  allow-listed APHC paths and cached on disk with metadata.
* The case summary is GENERATED by AdvocateMate and is stamped on every page as
  not being an official court document.
* Per-case official orders are not served: no verified retrieval path exists yet.
"""

from __future__ import annotations

import hashlib
import os
from datetime import date, timedelta
from pathlib import Path

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.core.config import get_settings
from app.core.errors import NotFound
from app.db.base import as_utc, utcnow
from app.integrations.aphc.client import WEEKLY_PDF_PATH
from app.models import Case, PdfDocument, PublicationStatus
from app.services import circuit, sources
from app.services.upstream_errors import translate_upstream

GENERATED_DISCLAIMER = (
    "GENERATED BY ADVOCATEMATE FROM PUBLIC APHC DATA - NOT AN OFFICIAL COURT DOCUMENT OR ORDER"
)


def _storage() -> Path:
    p = Path(get_settings().storage_dir) / "pdf"
    p.mkdir(parents=True, exist_ok=True)
    return p


def _save(db: Session, *, kind: str, cache_key: str, content: bytes, official: bool, ttl: timedelta, **meta) -> PdfDocument:
    digest = hashlib.sha256(content).hexdigest()
    path = _storage() / f"{kind}-{digest[:24]}.pdf"
    if not path.exists():
        tmp = path.with_suffix(".tmp")
        tmp.write_bytes(content)
        os.replace(tmp, path)
    doc = db.scalar(select(PdfDocument).where(PdfDocument.kind == kind, PdfDocument.cache_key == cache_key))
    if doc is None:
        doc = PdfDocument(kind=kind, cache_key=cache_key, is_official=official, storage_path=str(path),
                          sha256=digest, size_bytes=len(content), expires_at=utcnow() + ttl, **meta)
        db.add(doc)
    else:
        doc.storage_path, doc.sha256, doc.size_bytes = str(path), digest, len(content)
        doc.fetched_at, doc.expires_at = utcnow(), utcnow() + ttl
        for k, v in meta.items():
            setattr(doc, k, v)
    db.flush()
    return doc


def _cached(db: Session, kind: str, key: str) -> PdfDocument | None:
    doc = db.scalar(select(PdfDocument).where(PdfDocument.kind == kind, PdfDocument.cache_key == key))
    if doc and as_utc(doc.expires_at) > utcnow() and Path(doc.storage_path).exists():
        return doc
    return None


def _fetch_official(db: Session, kind: str, key: str, path: str, ttl: timedelta, **meta) -> PdfDocument:
    cached = _cached(db, kind, key)
    if cached:
        return cached
    client = sources.aphc_client()
    try:
        with translate_upstream():
            content, last_modified = circuit.call(circuit.HCDBS_PDF, lambda: client.download_pdf(path))
    finally:
        client.close()
    base = get_settings().aphc_base_url.rstrip("/")
    return _save(db, kind=kind, cache_key=key, content=content, official=True, ttl=ttl,
                 source_url=f"{base}{path}", source_last_modified=last_modified, **meta)


def weekly_cause_list_pdf(db: Session) -> PdfDocument:
    return _fetch_official(db, "weekly_cause_list", "current", WEEKLY_PDF_PATH, timedelta(hours=1))


def court_cause_list_pdf(db: Session, list_date: date, court_no: str) -> PdfDocument:
    row = db.scalar(
        select(PublicationStatus).where(PublicationStatus.list_date == list_date, PublicationStatus.court_no == court_no)
    )
    if row is None or not row.pdf_path:
        raise NotFound("APHC has not published a PDF for this court and date", code="pdf_unavailable")
    return _fetch_official(db, "court_cause_list", f"{list_date.isoformat()}:{court_no}", row.pdf_path,
                           timedelta(hours=2), list_date=list_date, court_no=court_no)


def case_summary_pdf(db: Session, case: Case, details: dict) -> PdfDocument:
    content = render_case_summary(details)
    return _save(db, kind="case_summary_generated", cache_key=str(case.id), content=content, official=False,
                 ttl=timedelta(minutes=10), case_id=case.id)


def render_case_summary(details: dict) -> bytes:
    from io import BytesIO

    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import getSampleStyleSheet
    from reportlab.lib.units import mm
    from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle

    buf = BytesIO()
    styles = getSampleStyleSheet()
    navy = colors.HexColor("#0B1F3A")

    def stamp(canvas, doc):
        canvas.saveState()
        canvas.setFillColor(colors.HexColor("#B00020"))
        canvas.setFont("Helvetica-Bold", 7.5)
        canvas.drawCentredString(A4[0] / 2, 10 * mm, GENERATED_DISCLAIMER)
        canvas.setFillColor(colors.HexColor("#999999"))
        canvas.setFont("Helvetica", 7)
        canvas.drawRightString(A4[0] - 15 * mm, 6 * mm, f"Page {doc.page}")
        canvas.restoreState()

    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=15 * mm, rightMargin=15 * mm, topMargin=15 * mm,
                            bottomMargin=18 * mm, title="Case summary (AdvocateMate generated)")
    story = [
        Paragraph("<font color='#0B1F3A'><b>Case Summary</b></font>", styles["Title"]),
        Paragraph(f"<font color='#B00020'><b>{GENERATED_DISCLAIMER}</b></font>", styles["Normal"]),
        Spacer(1, 6),
    ]

    def esc(v) -> str:
        return str(v).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    def section(title: str, data: dict):
        rows = [[Paragraph(f"<b>{esc(k.replace('_', ' ').title())}</b>", styles["BodyText"]),
                 Paragraph(esc(v), styles["BodyText"])] for k, v in data.items() if not isinstance(v, list | dict)]
        if not rows:
            return
        story.append(Paragraph(f"<font color='#0B1F3A'><b>{title}</b></font>", styles["Heading3"]))
        t = Table(rows, colWidths=[50 * mm, 125 * mm])
        t.setStyle(TableStyle([("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#CCCCCC")),
                               ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#F2F4F7")),
                               ("VALIGN", (0, 0), (-1, -1), "TOP")]))
        story.append(t)
        story.append(Spacer(1, 6))

    def people(title: str, items: list[dict], fields: list[str]):
        if not items:
            return
        story.append(Paragraph(f"<font color='#0B1F3A'><b>{title}</b></font>", styles["Heading3"]))
        head = [Paragraph(f"<b>{f.replace('_', ' ').title()}</b>", styles["BodyText"]) for f in fields]
        body = [[Paragraph(esc(i.get(f, "")), styles["BodyText"]) for f in fields] for i in items]
        t = Table([head] + body, repeatRows=1)
        t.setStyle(TableStyle([("GRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#CCCCCC")),
                               ("BACKGROUND", (0, 0), (-1, 0), navy), ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                               ("VALIGN", (0, 0), (-1, -1), "TOP")]))
        story.append(t)
        story.append(Spacer(1, 6))

    section("Case identity", details.get("identity", {}))
    section("Case information", details.get("information", {}))
    parties = details.get("parties", {})
    people("Petitioners", parties.get("petitioners", []), ["party_no", "name", "description"])
    people("Respondents", parties.get("respondents", []), ["party_no", "name", "description"])
    people("Vakalath", details.get("advocates", {}).get("vakalath", []),
           ["side", "party_no", "advocate_name", "advocate_code"])
    people("Observed listings", details.get("additional", {}).get("observed_listings", []),
           ["list_date", "list_type", "court_no", "item_no", "stage"])
    prov = details.get("provenance", {})
    story.append(Paragraph(
        f"Source: {esc(prov.get('source') or 'APHC public website')} | data fetched at: "
        f"{esc(prov.get('fetched_at') or 'n/a')} | generated at: {utcnow().isoformat(timespec='seconds')}",
        styles["Italic"]))
    doc.build(story, onFirstPage=stamp, onLaterPages=stamp)
    return buf.getvalue()


def require_file(doc: PdfDocument) -> Path:
    path = Path(doc.storage_path)
    if not path.exists():
        raise NotFound("PDF file is no longer available")
    return path
